import { Logout } from '@mesx/common-ui-lib';
import { User } from 'oidc-client';
import { createRouter, createWebHistory } from 'vue-router';
import { useProfileStore } from '@/Auth/store/user-auth-store';
import unauthorized from '@/global-components/reusable/Unauthorized.vue';
import loadingComponent from '@/global-components/reusable/loading.vue';
import appLogger from '@/utils/logger/app-logger.ts';

const routes = [
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const profileStore = useProfileStore();
        profileStore.initializeAuthentication();
        router.push('/cnerr-ui');
      },
    },
  },
  {
    component: unauthorized,

    name: 'Unauthorized',
    path: '/unauthorized',
  },
  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: '/loading',
  },
];

export const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.requiresAuth) {
    try {
      const userAuth = useProfileStore();
      if (userAuth.isLeader) {
        await userAuth.initializeAuthentication();
      } else {
        const tokenMessage = await new Promise<void | {
          type: string;
          user?: User;
        }>((resolve) => {
          const handler = (message: { type: string; user?: User }): void => {
            if (message.type === 'token-update' && message.user) {
              userAuth.tokenChannel.removeEventListener('message', handler);
              resolve(message);
            }
          };

          userAuth.tokenChannel.addEventListener('message', handler);

          setTimeout(() => {
            userAuth.tokenChannel.removeEventListener('message', handler);
            resolve();
          }, 1000);
        });

        if (tokenMessage?.user) {
          await userAuth.userManager.storeUser(tokenMessage.user);
          appLogger.log('[Follower] Token received and stored from leader');
        } else {
          appLogger.log(
            '[Follower] Token not received, requesting from leader...',
          );
          await userAuth.requestTokenFromLeader(); // Ici, le follower demande explicitement le token au leader
        }
      }

      await userAuth.authenticateUser();
      await userAuth.fetchUserAttributes();
      const isAuth = await userAuth.isAuthenticated();
      if (!isAuth) {
        console.warn('User not authenticated. Redirecting to /unauthorized.');
        return next('/loading');
      }

      const user = await userAuth.getUser();
      if (user) {
        await userAuth.authorizeUser();
      } else {
        // Handle the case where the user is null
        console.error('User not found');
        return next('/unauthorized'); // Return is added here
      }

      // Proceed to the route
      return next(); // Explicit return added
    } catch (error) {
      console.error(`Authentication error: ${error}`);
      return next('/unauthorized');
    }
  } else {
    return next(); // Pas besoin d'auth
  }
});

